'use strict';
/**
 * b311 signal — the invoice run is coming up and next month is unstarted.
 *
 * Toby's own example: "invoices are going out in three days have you done them
 * yet". The reason this is a signal and not a cron reminder is the second half
 * of the sentence — it only speaks if the invoices are NOT done.
 *
 * THE QUESTION
 *   Is the invoice run for the next billing month within `lead_days`, and does
 *   that period have no invoices at all?
 *
 * Invoices are stored per (period_year, period_month) and generated by a person
 * pressing Generate — b202 established that invoicing is a button, not a cron,
 * and this build does not change that. It only notices.
 *
 * The run day is settings.invoice_run_day (seeded 25). It is a separate number
 * from invoice_due_day (15), which is when the PARENT has to pay.
 */

const U = require('./_util');

module.exports = {
  key: 'invoice_run_due',
  label: 'Invoice run coming up, next month unstarted',
  question: 'Is the invoice run within N days with no invoices yet for that period?',
  category: 'signal_invoice_run',
  priority: 10,
  recipients: 'all-managers',
  link: '/admin/finance/invoices',
  defaults: {
    lead_days: 3,        // start speaking this many days before the run day
    grace_days: 5,       // keep speaking this many days after it, then stop
    cooldown_hours: 48,
    min_gap_hours: 24,
  },

  async evaluate(ctx) {
    const { db, today, cfg } = ctx;
    const runDay = parseInt(await ctx.setting('invoice_run_day', '25'), 10) || 25;

    // The billing period the next run covers: the month after the month the run
    // day falls in. Standing on 26 Sep, the 25 Sep run has passed, so the next
    // one is 25 Oct for November.
    const t = U.parts(today);
    let runDate = U.dayOfMonth(t.y, t.m, runDay);
    if (U.daysBetween(today, runDate) < -cfg.grace_days) {
      const nm = U.nextMonth(t.y, t.m);
      runDate = U.dayOfMonth(nm.y, nm.m, runDay);
    }
    const rd = U.parts(runDate);
    const period = U.nextMonth(rd.y, rd.m);
    const daysAway = U.daysBetween(today, runDate);

    // Outside the window there is nothing to say. This is the branch that runs
    // on ~24 days of every month, and it is the whole point of the build.
    if (daysAway > cfg.lead_days || daysAway < -cfg.grace_days) return null;

    const { rows } = await db.query(
      `SELECT count(*)::int AS n,
              count(*) FILTER (WHERE status = 'draft')::int AS drafts,
              count(sent_at)::int AS sent
         FROM invoices
        WHERE period_year = $1 AND period_month = $2
          AND credit_note_for_id IS NULL`,
      [period.y, period.m]);
    const n = rows[0].n, drafts = rows[0].drafts, sent = rows[0].sent;

    const label = U.monthLabel(period.y, period.m);
    const when = daysAway >= 0
      ? `The run is due on the ${U.ordinal(runDay)} — ${U.inDays(daysAway)}.`
      : `The run was due on the ${U.ordinal(runDay)}, ${U.inDays(daysAway)}.`;

    // 28 Oct 2026 (Toby: "I just realised I didn't send invoices out"): generated
    // is not the same as sent. Once the run day has passed, a period with
    // invoices but not one of them sent still needs him. One sent invoice counts
    // as "the run went out" — single late or held-back invoices are not this
    // signal's question.
    if (n > 0 && sent === 0 && daysAway < 0) {
      return {
        fingerprint: U.fingerprint({ period: `${period.y}-${period.m}`, n, sent }),
        headline: `${label} invoices have been made but none have been sent. ${when} ${n} invoice${n === 1 ? '' : 's'} waiting.`,
        facts: { period_year: period.y, period_month: period.m, run_date: runDate,
                 days_away: daysAway, invoices_for_period: n, drafts, sent },
      };
    }
    if (n > 0) return null;   // started. Silence is the success case.

    return {
      fingerprint: U.fingerprint({ period: `${period.y}-${period.m}`, n }),
      headline: `${label} invoices have not been started. ${when} There are 0 invoices for that period.`,
      facts: { period_year: period.y, period_month: period.m, run_date: runDate,
               days_away: daysAway, invoices_for_period: n, drafts },
    };
  },
};
